import { delegate, type SafeHtml } from 'kerfjs';
import { TokenSearchField, readTokenSearchField, placeTokenSearchCaret } from '@kerfjs/ui/token-search-field';
import '@kerfjs/ui/layout.css';
import './search.css';

type Token = { id: string; label: string; value: string };
type Expression = { text: string; tokens: Token[] };
type Snapshot = ReturnType<typeof readTokenSearchField>;
export interface SearchApplication {
  renderInto(root: HTMLElement, view: SafeHtml): void;
  initial: Expression;
  // Domain grammar and suggestions belong to this adapter, not the UI package.
  parse(snapshot: Snapshot): Expression;
  suggestions(draft: string): Array<{ value: string; label: string }>;
  token(value: string, id: string): Token | null;
  search(expression: Expression): void;
}
export function mountSearch(root: HTMLElement, app: SearchApplication) {
  let expression = app.initial;
  let editing: string | null = null;
  let draft = '';
  let message = '';
  let composing = false;
  const editor = () => root.querySelector<HTMLElement>('.kui-token-search__editor')!;
  function render() {
    app.renderInto(root, <section class="search kui-layout kui-section-stack" aria-label="Task search">
      <TokenSearchField id="task-search" label="Search tasks and filters"
        text={expression.text} tokens={expression.tokens}
        editAction="search.edit-token" removeAction="search.remove-token" clearAction="search.clear" />
      <p class="search-help">Type search text. Use each filter's edit or remove button to change it. Apply search to parse new filters.</p>
      <div class="kui-control-cluster">
        <button type="button" data-action="search.apply">Apply search</button>
      </div>
      {editing !== null && <div class="kui-section-stack" role="group" aria-label="Edit filter">
        <label for="filter-draft">Filter expression</label>
        <input id="filter-draft" value={draft} data-search-draft="true" />
        <div class="kui-control-cluster">
          <button type="button" data-action="search.save-token">Replace filter</button>
          <button type="button" data-action="search.cancel-token">Cancel edit</button>
        </div>
        <div class="search-suggestions" aria-label="Suggested filters">
          {app.suggestions(draft).map(option => <button type="button" data-action="search.suggestion" data-value={option.value}>{option.label}</button>)}
        </div>
      </div>}
      <p role="status" aria-live="polite" aria-atomic="true">{message}</p>
    </section>);
  }
  function snapshot() {
    return app.parse(readTokenSearchField(editor()));
  }
  function replace(next: Expression, announcement: string) {
    expression = next; editing = null; message = announcement;
    // This is an intentional controlled replacement, unlike ordinary typing.
    editor().textContent = '';
    render();
    placeTokenSearchCaret(editor(), 'end');
    app.search(expression);
  }
  const disposers: Array<() => void> = [];
  render();
  disposers.push(delegate(root, 'input', '.kui-token-search__editor', () => {
    if (composing) return;
    expression = snapshot();
    app.search(expression);
    // Do not render: browser-owned text and caret survive each keystroke.
  }));
  const compositionStart = () => { composing = true; };
  const compositionEnd = () => { composing = false; expression = snapshot(); app.search(expression); };
  root.addEventListener('compositionstart', compositionStart);
  root.addEventListener('compositionend', compositionEnd);
  disposers.push(delegate(root, 'input', '[data-search-draft]', (_event, element) => {
    draft = (element as HTMLInputElement).value;
    // Only replace the suggestions surface; preserve the input's DOM value/caret.
    const suggestions = root.querySelector<HTMLElement>('.search-suggestions')!;
    app.renderInto(suggestions, <>{app.suggestions(draft).map(option =>
      <button type="button" data-action="search.suggestion" data-value={option.value}>{option.label}</button>)}</>);
  }));
  disposers.push(delegate(root, 'click', '[data-action]', (_event, element) => {
    const node = element as HTMLElement;
    const action = node.dataset.action;
    if (action === 'search.clear') {
      editor().textContent = '';
      replace({ text: '', tokens: [] }, 'Search cleared');
    } else if (action === 'search.apply') {
      replace(snapshot(), 'Search applied');
    } else if (action === 'search.edit-token' || action === 'search.remove-token') {
      const chip = node.closest('.kui-token-search__token');
      const index = Array.from(editor().querySelectorAll('.kui-token-search__token')).indexOf(chip!);
      // Read before any controlled replacement, preserving token order and free text.
      const current = snapshot();
      const token = current.tokens[index];
      if (!token) return;
      if (action === 'search.remove-token') {
        replace({ ...current, tokens: current.tokens.filter(t => t.id !== token.id) }, 'Removed filter ' + token.label);
      } else {
        expression = current; editing = token.id; draft = token.value; render();
        root.querySelector<HTMLInputElement>('#filter-draft')?.focus();
      }
    } else if (action === 'search.cancel-token') {
      editing = null; render(); placeTokenSearchCaret(editor(), 'end');
    } else if (action === 'search.save-token' || action === 'search.suggestion') {
      if (editing === null) return;
      const replacement = app.token(action === 'search.suggestion' ? node.dataset.value ?? '' : draft, editing);
      if (!replacement) {
        message = 'That filter is not recognized. Choose a suggestion or revise it.';
        const live = root.querySelector<HTMLElement>('[role="status"]')!;
        live.textContent = message;
        root.querySelector<HTMLInputElement>('#filter-draft')?.focus();
        return;
      }
      replace({ ...expression, tokens: expression.tokens.map(token => token.id === editing ? replacement : token) }, 'Filter replaced with ' + replacement.label);
    }
  }));
  disposers.push(delegate(root, 'keydown', '.kui-token-search__editor, [data-search-draft]', (event, element) => {
    const key = event as KeyboardEvent;
    if (key.isComposing || composing) return;
    if (key.key === 'Enter' && element.matches('.kui-token-search__editor')) {
      key.preventDefault(); replace(snapshot(), 'Search applied');
    } else if (key.key === 'Escape' && editing !== null) {
      key.preventDefault(); editing = null; render(); placeTokenSearchCaret(editor(), 'end');
    }
  }));
  return () => {
    disposers.forEach(dispose => dispose());
    root.removeEventListener('compositionstart', compositionStart);
    root.removeEventListener('compositionend', compositionEnd);
  };
}

