.search { min-width: 0; color: var(--kui-color-text); }
.search-help { margin: 0; color: var(--kui-color-text-quiet); }
.search-suggestions { display: flex; flex-wrap: wrap; gap: var(--kui-layout-control-gap); }
.search button, .search input { font: inherit; min-height: 2.25rem; border: 1px solid var(--kui-color-border); border-radius: var(--kui-radius-m); color: var(--kui-color-text); background: var(--kui-color-surface); }
.search :focus-visible { outline: var(--kui-focus-ring); outline-offset: 2px; }
